# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TAİF\'TE İSLAM\'IN YAYILMA SÜRECİ VE SAKÎF HEYETİ (630 / H. 9)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">TAİF KUŞATMASI VE URVE BİN MES\'ÛD (RA)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Huneyn Gazvesi sonrası Taif Kalesi kuşatıldı (630).</text>\n  <text x="35" y="110" font-size="11.2" fill="#1e3a8a">• Kuşatma kaldırılırken Hz. Peygamber (sav):</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">  «Allah\'ım! Sakîf\'e hidayet ver ve onları bize getir!»</text>\n  <text x="35" y="150" font-size="11.2" fill="#1e3a8a">• Urve bin Mes\'ûd es-Sekafî (ra) Medine\'ye gelip</text>\n  <text x="35" y="168" font-size="11.2" fill="#1e3a8a">  Müslüman oldu; Taif\'te ezan okurken şehit edildi.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SAKÎF HEYETİ VE İLKELİ TEVHİT DURUŞU</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Abdüyâlîl bin Amr başkanlığında 6 kişilik heyet</text>\n  <text x="370" y="106" font-size="11.2" fill="#14532d">  Ramazan 9 (630) ayında Mescid-i Nebevî\'de ağırlandı.</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">• Lât putunun 3 yıl kalması ve namazdan muafiyet</text>\n  <text x="370" y="146" font-size="11.2" fill="#14532d">  talebi reddedildi: «Rükûsuz (namazsız) dinde hayır yoktur!»</text>\n  <text x="370" y="168" font-size="11.2" font-weight="bold" fill="#166534">• Genç vali ve muallim: Osman bin Ebü\'l-Âs (ra)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Lât putu Ebû Süfyan bin Harb ve Mugîre bin Şu\'be (ra) eliyle yıkılmış, Taif tevhit ve ilim merkezi olmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HZ. EBÛ BEKİR\'İN (RA) HAYATI, ŞAHSİYETİ VE İSLAM\'A GİRİŞİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">KİMLİĞİ, LAKAPLARI VE İSLAM ÖNCESİ HAYATI</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Asıl adı: Abdullah bin Osman (Ebû Kuhâfe) et-Teymî</text>\n  <text x="35" y="110" font-size="11.2" fill="#713f12">• Lakapları: es-Sıddîk (tereddütsüz tasdik eden),</text>\n  <text x="35" y="128" font-size="11.2" fill="#713f12">  el-Atîk (cehennemden azatlı / güzel yüzlü ve soylu)</text>\n  <text x="35" y="150" font-size="11.2" fill="#713f12">• Cahiliye\'de puta tapmadı, içki içmedi; Kureyş\'te</text>\n  <text x="35" y="168" font-size="11.2" fill="#713f12">  ensâb (soy bilgisi) alimi ve dürüst bir tüccardı.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">TEBLİĞDEKİ ROLÜ VE İNFAK KAHRAMANLIĞI</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Davetine icabetle Müslüman olan Aşere-i Mübeşşere:</text>\n  <text x="370" y="106" font-size="11.2" fill="#581c87">  Hz. Osman, Zübeyr bin Avvâm, Abdurrahman bin Avf,</text>\n  <text x="370" y="124" font-size="11.2" fill="#581c87">  Sa\'d bin Ebî Vakkâs ve Talha bin Ubeydullah (ra)</text>\n  <text x="370" y="146" font-size="11.2" fill="#581c87">• Servetiyle Bilâl-i Habeşî, Âmir bin Füheyre gibi</text>\n  <text x="370" y="164" font-size="11.2" fill="#581c87">  mazlum köleleri satın alarak Allah rızası için azat etti.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">«İslam\'a davet ettiğim herkes biraz durakladı; yalnız Ebû Bekir tereddüt etmeden iman etti.» (Hadis-i Şerif)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">TAİF VE MEKKE SÜRECİNDE NEBEVİ TEBLİĞ İLKELERİ KARŞILAŞTIRMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">AF, MERHAMET VE İNSAN KAZANMA</text>\n  <text x="35" y="88" font-size="11.2" fill="#7c2d12">• 620 yılındaki taşlama hadisesinde beddua yerine</text>\n  <text x="35" y="106" font-size="11.2" fill="#7c2d12">  «Onların neslinden tevhit ehli çıkar» duası</text>\n  <text x="35" y="128" font-size="11.2" fill="#7c2d12">• Ci\'râne\'de Hevâzin esirlerinin karşılıksız</text>\n  <text x="35" y="146" font-size="11.2" fill="#7c2d12">  serbest bırakılması ve Mâlik bin Avf\'ın İslam\'a girişi</text>\n  <text x="35" y="168" font-size="11.2" fill="#7c2d12">• Sakîf heyetinin Mescid-i Nebevî\'de çadırda ağırlanması</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">TEVHİTTE KARARLILIK VE SADAKAT ÖRNEKLİĞİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• İnanç ve ibadet esaslarında (şirkten arınma ve</text>\n  <text x="370" y="106" font-size="11.2" fill="#164e63">  namaz) taviz vermeyen ilkeli tebliğ duruşu</text>\n  <text x="370" y="128" font-size="11.2" fill="#164e63">• Hz. Ebû Bekir\'in (ra) İsrâ-Miraç hadisesinde ve</text>\n  <text x="370" y="146" font-size="11.2" fill="#164e63">  Sevr Mağarası\'nda («Üzülme, Allah bizimledir») sadakati</text>\n  <text x="370" y="168" font-size="11.2" font-weight="bold" fill="#155e75">• Kur\'an\'da \'ikinin ikincisi\' (sâniye isneyn — Tevbe 40)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Nebevi yöntem; insanlara karşı sonsuz şefkat ve merhameti, tevhit ilkelerinde ise tavizsiz sadakati birleştirir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
